-- Spoken RP follow-ups. Never /me: the WoW client supplies its own emote.
local _, addon = ...
-- Fully qualified addon table paths stay editable in RPTextStudio.
addon.localeData.deDE.generalTexts.AGREE = { gruppe = { "Da sind wir uns ausnahmsweise einig.", "Euer Gedanke hat Hand und Fuß." }, ziel = { "%s, da stimme ich Euch zu.", "%s: Euer Gedanke hat Hand und Fuß." } }
addon.localeData.deDE.generalTexts.AMAZE = { gruppe = { "Das verschlägt selbst mir die Sprache.", "Bei allen Sternen, wie ist das möglich?" }, ziel = { "%s, Ihr überrascht mich wirklich.", "%s: Bei allen Sternen, wie ist das möglich?" } }
addon.localeData.deDE.generalTexts.ANGRY = { gruppe = { "Meine Geduld hat gerade Feierabend gemacht.", "Wagt es nicht, das noch einmal zu versuchen." }, ziel = { "%s, Ihr reizt meine Geduld bis zum Äußersten.", "%s: Wagt es nicht, das noch einmal zu versuchen." } }
addon.localeData.deDE.generalTexts.ATTACKTARGET = { gruppe = { "Waffen bereit! Das Ziel steht fest.", "Keine langen Reden, konzentriert Euch auf den Gegner!" }, ziel = { "Auf %s! Haltet die Reihen zusammen!", "%s: Keine langen Reden, konzentriert Euch auf den Gegner!" } }
addon.localeData.deDE.generalTexts.BARK = { gruppe = { "Wuff! Das sollte wohl deutlich genug sein.", "Manchmal versteht ein Hund mehr als ein Ratsherr." }, ziel = { "%s, ist das deutlich genug für Euch?", "%s: Manchmal versteht ein Hund mehr als ein Ratsherr." } }
addon.localeData.deDE.generalTexts.BASHFUL = { gruppe = { "Ein wenig weniger Aufmerksamkeit wäre angenehm.", "Ich bin ein Held, nicht die Hauptattraktion." }, ziel = { "%s, Ihr bringt mich noch zum Erröten.", "%s: Ich bin ein Held, nicht die Hauptattraktion." } }
addon.localeData.deDE.generalTexts.BECKON = { gruppe = { "Kommt näher, hier lässt sich besser reden.", "Keine Sorge, ich habe heute noch niemanden gebissen." }, ziel = { "%s, kommt doch zu uns herüber!", "%s: Keine Sorge, ich habe heute noch niemanden gebissen." } }
addon.localeData.deDE.generalTexts.BEG = { gruppe = { "Ein kleines bisschen Hilfe würde Wunder wirken.", "Ich frage nicht gern zweimal, aber ich würde es tun." }, ziel = { "%s, habt Ihr ein wenig Erbarmen?", "%s: Ich frage nicht gern zweimal, aber ich würde es tun." } }
addon.localeData.deDE.generalTexts.BELCH = { gruppe = { "Verzeiht. Das Essen hatte offenbar etwas zu sagen.", "Ein guter Braten führt manchmal das letzte Wort." }, ziel = { "%s, ich hoffe, Ihr nehmt es mir nicht übel.", "%s: Ein guter Braten führt manchmal das letzte Wort." } }
addon.localeData.deDE.generalTexts.BITE = { gruppe = { "Nicht jede Drohung braucht eine Klinge.", "Ich habe noch Zähne und erstaunlich wenig Geduld." }, ziel = { "%s, kommt meinen Zähnen besser nicht zu nahe.", "%s: Ich habe noch Zähne und erstaunlich wenig Geduld." } }
addon.localeData.deDE.generalTexts.BLEED = { gruppe = { "Ein Kratzer nur. Ein ausgesprochen hartnäckiger.", "Wer hat behauptet, Helden bluteten nicht?" }, ziel = { "%s, ein Verband wäre jetzt willkommen.", "%s: Wer hat behauptet, Helden bluteten nicht?" } }
addon.localeData.deDE.generalTexts.BLINK = { gruppe = { "Habe ich das eben richtig gesehen?", "Meine Augen verlangen eine zweite Erklärung." }, ziel = { "%s, wiederholt das bitte für meine Augen.", "%s: Meine Augen verlangen eine zweite Erklärung." } }
addon.localeData.deDE.generalTexts.BLOW = { gruppe = { "Ein Kuss auf Reisen braucht Rückenwind.", "Möge die Brise ein freundliches Zeichen tragen." }, ziel = { "%s, diesen Luftkuss schicke ich Euch.", "%s: Möge die Brise ein freundliches Zeichen tragen." } }
addon.localeData.deDE.generalTexts.BLUSH = { gruppe = { "Nun, das war jetzt ausgesprochen unerwartet.", "Meine Wangen verraten mich heute schneller als Worte." }, ziel = { "%s, Ihr macht mir die Antwort nicht gerade leicht.", "%s: Meine Wangen verraten mich heute schneller als Worte." } }
addon.localeData.deDE.generalTexts.BOGGLE = { gruppe = { "Dafür fehlen mir gleich mehrere passende Worte.", "Mein Verstand bittet um eine kurze Pause." }, ziel = { "%s, erklärt mir bitte, was hier geschieht.", "%s: Mein Verstand bittet um eine kurze Pause." } }
addon.localeData.deDE.generalTexts.BONK = { gruppe = { "Manchmal hilft nur ein kleiner Hinweis mit Nachdruck.", "Das war eine Lehre, keine Kriegserklärung." }, ziel = { "%s, merkt Euch diese freundliche Ermahnung.", "%s: Das war eine Lehre, keine Kriegserklärung." } }
addon.localeData.deDE.generalTexts.BORED = { gruppe = { "Würde bitte jemand das Abenteuer wieder einschalten?", "Ich habe schon spannendere Steine betrachtet." }, ziel = { "%s, habt Ihr zufällig eine bessere Idee?", "%s: Ich habe schon spannendere Steine betrachtet." } }
addon.localeData.deDE.generalTexts.BOUNCE = { gruppe = { "Heute hält mich kein Stuhl lange fest.", "Die Füße haben offenbar eigene Pläne." }, ziel = { "%s, kommt schon, bewegt Euch ein wenig!", "%s: Die Füße haben offenbar eigene Pläne." } }
addon.localeData.deDE.generalTexts.BRB = { gruppe = { "Ein kurzer Abstecher, ich bin gleich zurück.", "Haltet den Platz frei und die Suppe warm." }, ziel = { "%s, ich bin in einem Augenblick wieder da.", "%s: Haltet den Platz frei und die Suppe warm." } }
addon.localeData.deDE.generalTexts.CACKLE = { gruppe = { "Ha! Die Sache wird immer unterhaltsamer.", "Ich sollte vielleicht weniger Freude daran haben." }, ziel = { "%s, das habt Ihr Euch selbst eingebrockt!", "%s: Ich sollte vielleicht weniger Freude daran haben." } }
addon.localeData.deDE.generalTexts.CALM = { gruppe = { "Ruhig. Wir gewinnen nichts durch Hast.", "Ein klarer Kopf ist eine zuverlässige Waffe." }, ziel = { "%s, atmet erst einmal durch.", "%s: Ein klarer Kopf ist eine zuverlässige Waffe." } }
addon.localeData.deDE.generalTexts.CHARGE = { gruppe = { "Vorwärts! Der Weg öffnet sich nicht von allein.", "Für die Mutigen gibt es keinen Rückwärtsgang." }, ziel = { "Mit mir, %s! Jetzt geht es los!", "%s: Für die Mutigen gibt es keinen Rückwärtsgang." } }
addon.localeData.deDE.generalTexts.CHEW = { gruppe = { "Diese Ration verdient eine gründliche Überprüfung.", "Wer hastig kaut, verpasst den halben Geschmack." }, ziel = { "%s, wollt Ihr auch ein Stück?", "%s: Wer hastig kaut, verpasst den halben Geschmack." } }
addon.localeData.deDE.generalTexts.CHICKEN = { gruppe = { "Gack! Das war eindeutig ein taktischer Rückzug.", "Man muss kein Huhn sein, um Gefahren zu erkennen." }, ziel = { "%s, gackert Ihr nur oder handelt Ihr auch?", "%s: Man muss kein Huhn sein, um Gefahren zu erkennen." } }
addon.localeData.deDE.generalTexts.CHUCKLE = { gruppe = { "Das war besser, als ich erwartet hatte.", "Ein kleines Lachen kann einen langen Tag retten." }, ziel = { "%s, Ihr versteht es, mich aufzuheitern.", "%s: Ein kleines Lachen kann einen langen Tag retten." } }
addon.localeData.deDE.generalTexts.COLD = { gruppe = { "Hat jemand zufällig ein zweites Paar Socken?", "Selbst meine Gedanken bekommen langsam Frost." }, ziel = { "%s, kennt Ihr einen wärmeren Ort?", "%s: Selbst meine Gedanken bekommen langsam Frost." } }
addon.localeData.deDE.generalTexts.CONFUSED = { gruppe = { "Die Karte und die Wirklichkeit sind sich uneinig.", "Ich bin nicht verloren. Ich prüfe Alternativen." }, ziel = { "%s, könnt Ihr mir den Zusammenhang erklären?", "%s: Ich bin nicht verloren. Ich prüfe Alternativen." } }
addon.localeData.deDE.generalTexts.CONGRATS = { gruppe = { "Das habt Ihr Euch mit harter Arbeit verdient!", "Heute dürfen wir die Erfolge zählen." }, ziel = { "%s, meinen herzlichen Glückwunsch!", "%s: Heute dürfen wir die Erfolge zählen." } }
addon.localeData.deDE.generalTexts.COUGH = { gruppe = { "Dieser Staub hätte draußen bleiben dürfen.", "Verzeiht, die Luft ist heute ausgesprochen widerspenstig." }, ziel = { "%s, habt Ihr etwas Wasser für mich?", "%s: Verzeiht, die Luft ist heute ausgesprochen widerspenstig." } }
addon.localeData.deDE.generalTexts.COWER = { gruppe = { "Vielleicht ist ein kleiner Schritt zurück klug.", "Mut und Übermut sind nicht dasselbe." }, ziel = { "%s, kommt lieber hinter diese Mauer.", "%s: Mut und Übermut sind nicht dasselbe." } }
addon.localeData.deDE.generalTexts.CRACK = { gruppe = { "Die Finger sind bereit. Der Rest muss folgen.", "Es wird Zeit, wieder in Bewegung zu kommen." }, ziel = { "%s, bereit für eine neue Runde?", "%s: Es wird Zeit, wieder in Bewegung zu kommen." } }
addon.localeData.deDE.generalTexts.CRINGE = { gruppe = { "Das hätte man eleganter lösen können.", "Ich tue einfach so, als hätte ich nichts gesehen." }, ziel = { "%s, sagt bitte, dass das nicht Euer Plan war.", "%s: Ich tue einfach so, als hätte ich nichts gesehen." } }
addon.localeData.deDE.generalTexts.CRY = { gruppe = { "Manchmal sind Worte einfach zu klein.", "Auch Tränen dürfen ihren Weg finden." }, ziel = { "%s, verzeiht, ich brauche einen Augenblick.", "%s: Auch Tränen dürfen ihren Weg finden." } }
addon.localeData.deDE.generalTexts.CURIOUS = { gruppe = { "Das sieht nach einer interessanten Geschichte aus.", "Ich würde gern wissen, wie das funktioniert." }, ziel = { "%s, erzählt mir mehr darüber.", "%s: Ich würde gern wissen, wie das funktioniert." } }
